; Plane low-turn check and drift
; $5c03-$5c0f

; Called when the plane banks. Below altitude 4 the wing touches the ground: sets the hit flag $4050.
plane_low_turn
        lda altitude
        cmp #$04
        bcs plane_low_turn_exit
        lda #$01
        sta crash_flag
plane_low_turn_exit
        rts
